core_reasoning_1:
\section*{Claim}
For a deterministic chemical reaction system with stoichiometric matrix \(S\), steady-state flux vector \(\bar r\), conserved quantities \(d^{(\bar\alpha)}\cdot \bar x=\Omega_{\bar\alpha}\), and kernel expansion \(\bar r_A=\sum_\alpha \mu_\alpha c_A^{(\alpha)}\), differentiation of the steady-state equations with respect to a reaction parameter \(k_B\) and a conserved-quantity value \(\Omega_{\bar\beta}\) gives
\[
\mathcal A\,\partial_B\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
=-\begin{pmatrix}r_{A,B}\\0\end{pmatrix},
\qquad
\mathcal A\,\partial_{\bar\beta}\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
=\begin{pmatrix}0\\ e_{\bar\beta}\end{pmatrix},
\]
where
\[
\mathcal A:=\begin{pmatrix}r_{A,i}&-c_A^{(\alpha)}\\ d_i^{(\bar\alpha)}&0\end{pmatrix}.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& S\bar r=0.\\
(P2)& d^{(\bar\alpha)}\cdot \bar x=\Omega_{\bar\alpha}\quad\text{for every conserved-quantity basis vector }d^{(\bar\alpha)}.\\
(P3)& \bar r_A=\sum_\alpha \mu_\alpha c_A^{(\alpha)},\quad \text{where }Sc^{(\alpha)}=0.\\
(P4)& r_{A,i}:=\left.\dfrac{\partial r_A(x;k_A)}{\partial x_i}\right|_{x=\bar x},\quad
r_{A,B}:=\left.\dfrac{\partial r_A(x;k_A)}{\partial k_B}\right|_{x=\bar x}.\\
(P5)& \partial_B\Omega_{\bar\alpha}=0,\quad \partial_{\bar\beta}\Omega_{\bar\alpha}=\delta_{\bar\alpha\bar\beta}.\\
(P6)& \mathcal A:=\begin{pmatrix}r_{A,i}&-c_A^{(\alpha)}\\ d_i^{(\bar\alpha)}&0\end{pmatrix}.
\end{array}
\]

\section*{Derivation}
Differentiate the kernel expansion in (P3) with respect to \(k_B\):
\begin{align}
\partial_B\bar r_A
&=\partial_B r_A(\bar x;k_A) &&\text{definition of }\bar r_A\\
&=\sum_i r_{A,i}\,\partial_B\bar x_i+r_{A,B} &&\text{chain rule and (P4)}\\
&=\sum_\alpha (\partial_B\mu_\alpha)c_A^{(\alpha)} &&\text{differentiate (P3)}.
\end{align}
Move all unknown sensitivities to the left:
\begin{align}
\sum_i r_{A,i}\,\partial_B\bar x_i-
\sum_\alpha c_A^{(\alpha)}\partial_B\mu_\alpha
&=-r_{A,B}. &&\text{rearrangement}
\end{align}
Differentiate the conserved quantities in (P2):
\begin{align}
\sum_i d_i^{(\bar\alpha)}\partial_B\bar x_i
&=\partial_B\Omega_{\bar\alpha}=0 &&\text{by (P2) and (P5)}.
\end{align}
Combining the last two displays with (P6) gives
\begin{align}
\mathcal A\,\partial_B\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
&=-\begin{pmatrix}r_{A,B}\\0\end{pmatrix}. &&\text{block form from (P6)}
\end{align}
The same calculation for \(\Omega_{\bar\beta}\) has no explicit reaction-rate term:
\begin{align}
\sum_i r_{A,i}\,\partial_{\bar\beta}\bar x_i-
\sum_\alpha c_A^{(\alpha)}\partial_{\bar\beta}\mu_\alpha
&=0 &&\text{chain rule; }r_A\text{ has no explicit }\Omega_{\bar\beta}\text{ term},\\
\sum_i d_i^{(\bar\alpha)}\partial_{\bar\beta}\bar x_i
&=\partial_{\bar\beta}\Omega_{\bar\alpha}=\delta_{\bar\alpha\bar\beta} &&\text{by (P5)},\\
\mathcal A\,\partial_{\bar\beta}\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
&=\begin{pmatrix}0\\ e_{\bar\beta}\end{pmatrix}. &&\text{block form from (P6)}
\end{align}

\section*{Final Result}
\[
\boxed{
\mathcal A\,\partial_B\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
=-\begin{pmatrix}r_{A,B}\\0\end{pmatrix},
\qquad
\mathcal A\,\partial_{\bar\beta}\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
=\begin{pmatrix}0\\ e_{\bar\beta}\end{pmatrix}}
\]

\hfill$\blacksquare$

core_reasoning_2:
\section*{Claim}
If \(\mathcal A\) is invertible and a perturbation of \(k_B\) has explicit derivative \(r_{C,B}=\rho_B\delta_{CB}\) with \(\rho_B\ne0\), then the species- and reaction-sensitivity matrices
\[
X_{iB}:=(\mathcal A^{-1})_{iB},
\qquad
R_{HB}:=\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha B}
\]
satisfy
\[
\partial_B\bar x_i=-\rho_BX_{iB},
\qquad
\partial_B\bar r_H=-\rho_BR_{HB}.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \mathcal A\,\partial_B\begin{pmatrix}\bar x\\ \mu\end{pmatrix}=-\begin{pmatrix}r_{C,B}\\0\end{pmatrix}.\\
(P2)& \mathcal A^{-1}\text{ exists}.\\
(P3)& r_{C,B}=\rho_B\delta_{CB},\quad \rho_B\ne0.\\
(P4)& \bar r_H=\sum_\alpha \mu_\alpha c_H^{(\alpha)}.\\
(P5)& X_{iB}:=(\mathcal A^{-1})_{iB}.\\
(P6)& R_{HB}:=\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha B}.
\end{array}
\]

\section*{Derivation}
Multiply (P1) by \(\mathcal A^{-1}\):
\begin{align}
\partial_B\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
&=-\mathcal A^{-1}\begin{pmatrix}r_{C,B}\\0\end{pmatrix} &&\text{by (P1) and (P2)}\\
&=-\mathcal A^{-1}\begin{pmatrix}\rho_B\delta_{CB}\\0\end{pmatrix} &&\text{by (P3)}.
\end{align}
Taking the species component gives
\begin{align}
\partial_B\bar x_i
&=-\sum_C(\mathcal A^{-1})_{iC}\rho_B\delta_{CB} &&\text{component form}\\
&=-\rho_B(\mathcal A^{-1})_{iB} &&\text{Kronecker-delta contraction}\\
&=-\rho_BX_{iB}. &&\text{by (P5)}
\end{align}
Taking the kernel-coordinate component gives
\begin{align}
\partial_B\mu_\alpha
&=-\sum_C(\mathcal A^{-1})_{\alpha C}\rho_B\delta_{CB} &&\text{component form}\\
&=-\rho_B(\mathcal A^{-1})_{\alpha B}. &&\text{Kronecker-delta contraction}
\end{align}
Differentiate the reaction flux expansion:
\begin{align}
\partial_B\bar r_H
&=\sum_\alpha c_H^{(\alpha)}\partial_B\mu_\alpha &&\text{differentiate (P4)}\\
&=-\rho_B\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha B} &&\text{substitute previous line}\\
&=-\rho_BR_{HB}. &&\text{by (P6)}
\end{align}

\section*{Final Result}
\[
\boxed{\partial_B\bar x_i=-\rho_BX_{iB},\qquad \partial_B\bar r_H=-\rho_BR_{HB}}
\]

\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
For a conserved-quantity perturbation \(\Omega_{\bar\beta}\), the qualitative zero pattern of species and reaction-rate responses is determined by the \(\bar\beta\)-column of \(\mathcal A^{-1}\):
\[
\partial_{\bar\beta}\bar x_i=(\mathcal A^{-1})_{i\bar\beta},
\qquad
\partial_{\bar\beta}\bar r_H=
\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha\bar\beta}.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \mathcal A\,\partial_{\bar\beta}\begin{pmatrix}\bar x\\ \mu\end{pmatrix}=\begin{pmatrix}0\\ e_{\bar\beta}\end{pmatrix}.\\
(P2)& \mathcal A^{-1}\text{ exists}.\\
(P3)& e_{\bar\beta}\text{ is the unit vector with component }(e_{\bar\beta})_{\bar\alpha}=\delta_{\bar\alpha\bar\beta}.\\
(P4)& \bar r_H=\sum_\alpha \mu_\alpha c_H^{(\alpha)}.
\end{array}
\]

\section*{Derivation}
Multiply (P1) by \(\mathcal A^{-1}\):
\begin{align}
\partial_{\bar\beta}\begin{pmatrix}\bar x\\ \mu\end{pmatrix}
&=\mathcal A^{-1}\begin{pmatrix}0\\ e_{\bar\beta}\end{pmatrix} &&\text{by (P1) and (P2)}.
\end{align}
Taking the species component gives
\begin{align}
\partial_{\bar\beta}\bar x_i
&=\sum_{\bar\alpha}(\mathcal A^{-1})_{i\bar\alpha}(e_{\bar\beta})_{\bar\alpha} &&\text{component form}\\
&=\sum_{\bar\alpha}(\mathcal A^{-1})_{i\bar\alpha}\delta_{\bar\alpha\bar\beta} &&\text{by (P3)}\\
&=(\mathcal A^{-1})_{i\bar\beta}. &&\text{Kronecker-delta contraction}
\end{align}
Taking the kernel-coordinate component gives
\begin{align}
\partial_{\bar\beta}\mu_\alpha
&=\sum_{\bar\alpha}(\mathcal A^{-1})_{\alpha\bar\alpha}\delta_{\bar\alpha\bar\beta} &&\text{component form and (P3)}\\
&=(\mathcal A^{-1})_{\alpha\bar\beta}. &&\text{Kronecker-delta contraction}
\end{align}
Differentiate the flux expansion:
\begin{align}
\partial_{\bar\beta}\bar r_H
&=\sum_\alpha c_H^{(\alpha)}\partial_{\bar\beta}\mu_\alpha &&\text{differentiate (P4)}\\
&=\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha\bar\beta}. &&\text{substitute previous line}
\end{align}

\section*{Final Result}
\[
\boxed{\partial_{\bar\beta}\bar x_i=(\mathcal A^{-1})_{i\bar\beta},\qquad
\partial_{\bar\beta}\bar r_H=\sum_\alpha c_H^{(\alpha)}(\mathcal A^{-1})_{\alpha\bar\beta}}
\]

\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
The influence relation is generically transitive in the following local form: if perturbing \(k_A\) changes the steady concentration of a reactant \(v_i\) of reaction \(e_B\), and perturbing \(k_B\) changes the steady flux of reaction \(e_C\), then perturbing \(k_A\) changes the steady flux of \(e_C\):
\[
e_A\rightsquigarrow v_i,
\quad v_i\in\operatorname{React}(e_B),
\quad e_B\rightsquigarrow e_C
\Longrightarrow
 e_A\rightsquigarrow e_C.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& e_A\rightsquigarrow v_i\text{ means }\partial_A\bar x_i\ne0.\\
(P2)& e_B\rightsquigarrow e_C\text{ means }\partial_B\bar r_C\ne0.\\
(P3)& v_i\in\operatorname{React}(e_B)\text{ and }(\log r_{B,B})_{,i}\ne0.\\
(P4)& F_{B,A}:=\sum_{j\in\operatorname{React}(e_B)}(\log r_{B,B})_{,j}\partial_A\bar x_j.\\
(P5)& \partial_{AB}\bar r_C=\partial_A\bar r_C F_{A,B}+\partial_B\bar r_C F_{B,A}
+\sum_{D,j,k}\partial_D\bar r_C\dfrac{r_{D,jk}}{r_{D,D}}\partial_A\bar x_j\partial_B\bar x_k.\\
(P6)& \text{No fine-tuning: if a displayed sum contains a nonzero term not forced to cancel, the sum is generically nonzero.}\\
(P7)& \bar r_{C,A}(k_B+\delta k_B)=\bar r_{C,A}(k_B)+\delta k_B\,\partial_{AB}\bar r_C+O((\delta k_B)^2).
\end{array}
\]

\section*{Derivation}
Use the definition of \(F_{B,A}\):
\begin{align}
F_{B,A}
&=\sum_{j\in\operatorname{React}(e_B)}(\log r_{B,B})_{,j}\partial_A\bar x_j &&\text{by (P4)}\\
&=(\log r_{B,B})_{,i}\partial_A\bar x_i
+\sum_{j\ne i}(\log r_{B,B})_{,j}\partial_A\bar x_j &&\text{separate the }j=i\text{ term}\\
&\ne0 &&\text{by (P1), (P3), and (P6)}.
\end{align}
Now inspect the second-order response formula:
\begin{align}
\partial_{AB}\bar r_C
&=\partial_A\bar r_C F_{A,B}+\partial_B\bar r_C F_{B,A}
+\sum_{D,j,k}\partial_D\bar r_C\frac{r_{D,jk}}{r_{D,D}}\partial_A\bar x_j\partial_B\bar x_k &&\text{by (P5)}\\
&\ne0 &&\text{because }\partial_B\bar r_C\ne0\text{ by (P2), }F_{B,A}\ne0\text{, and (P6)}.
\end{align}
Apply the Taylor expansion in \(k_B\):
\begin{align}
\bar r_{C,A}(k_B+\delta k_B)
&=\bar r_{C,A}(k_B)+\delta k_B\,\partial_{AB}\bar r_C+O((\delta k_B)^2) &&\text{by (P7)}\\
&\ne0 &&\text{for sufficiently small generic }\delta k_B\ne0.
\end{align}
Therefore perturbing \(k_A\) changes \(\bar r_C\):
\begin{align}
\bar r_{C,A}\ne0
&\Longleftrightarrow e_A\rightsquigarrow e_C. &&\text{definition of influence}
\end{align}

\section*{Final Result}
\[
\boxed{e_A\rightsquigarrow v_i,\\ v_i\in\operatorname{React}(e_B),\\ e_B\rightsquigarrow e_C
\Longrightarrow e_A\rightsquigarrow e_C}
\]

\hfill$\blacksquare$

core_reasoning_7:
\section*{Claim}
For the affected output-complete subnetwork \(\gamma_B=(V_B,E_B\cup E_B^+)\), the topological influence index vanishes:
\[
\lambda(\gamma_B):=-|V_B|+|E_B\cup E_B^+|-|(\ker S)_{\mathrm{supp}\,\gamma_B}|+|P^0_{\gamma_B}(\operatorname{coker}S)|=0.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \gamma_B=(V_B,E_B\cup E_B^+)\text{ is output-complete and has localized influence}.\\
(P2)& \text{After ordering the sensitivity matrix according to inside/outside degrees of freedom, the localized-response argument yields a block }\mathcal A_{11}.\\
(P3)& \mathcal A\text{ is invertible, and localized response forces }\mathcal A_{11}\text{ to be both full-column-rank and full-row-rank}.\\
(P4)& n:=|E_B\cup E_B^+|+|P^0_{\gamma_B}(\operatorname{coker}S)|\text{ is the number of rows of }\mathcal A_{11}.\\
(P5)& m:=|V_B|+|(\ker S)_{\mathrm{supp}\,\gamma_B}|\text{ is the number of columns of }\mathcal A_{11}.\\
(P6)& \text{A matrix that is both full-column-rank and full-row-rank satisfies }m\le n\text{ and }n\le m.\\
(P7)& \lambda(\gamma_B):=-|V_B|+|E_B\cup E_B^+|-|(\ker S)_{\mathrm{supp}\,\gamma_B}|+|P^0_{\gamma_B}(\operatorname{coker}S)|.
\end{array}
\]

\section*{Derivation}
Use the rank consequences in (P3):
\begin{align}
\mathcal A_{11}\text{ full-column-rank}
&\Longrightarrow m\le n &&\text{by (P6)},\\
\mathcal A_{11}\text{ full-row-rank}
&\Longrightarrow n\le m &&\text{by (P6)},\\
m&=n &&\text{combine the two inequalities}.
\end{align}
Substitute the definitions of \(m\) and \(n\):
\begin{align}
|V_B|+|(\ker S)_{\mathrm{supp}\,\gamma_B}|
&=|E_B\cup E_B^+|+|P^0_{\gamma_B}(\operatorname{coker}S)| &&\text{by (P4), (P5), and }m=n.
\end{align}
Move the left-hand side to the right-hand side:
\begin{align}
0
&=-|V_B|+|E_B\cup E_B^+|-|(\ker S)_{\mathrm{supp}\,\gamma_B}|+|P^0_{\gamma_B}(\operatorname{coker}S)| &&\text{rearrangement}\\
&=\lambda(\gamma_B). &&\text{by (P7)}
\end{align}

\section*{Final Result}
\[
\boxed{\lambda(\gamma_B)=0}
\]

\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
For a deterministic reaction system satisfying the paper's stability and generic-kinetics assumptions, elementary RPA properties are in one-to-one correspondence with labeled buffering structures.

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \text{For a parameter }p,\text{ its elementary RPA property is }(V\setminus V_p,E\setminus E_p),\\
&\text{where }V_p\text{ and }E_p\text{ are the species and reactions affected by perturbing }p.\\
(P2)& \text{The associated labeled subnetwork is }\gamma_p:=(V_p,E_p\cup E_p^+),\\
&\text{where }E_p^+\text{ minimally makes }(V_p,E_p\cup E_p^+)\text{ output-complete}.\\
(P3)& \text{Necessity: every elementary RPA property gives a labeled subnetwork }\gamma_p\text{ with }\lambda(\gamma_p)=0.\\
(P4)& \text{Sufficiency: if }\gamma_p=(V_p,E_p\cup E_p^+)\text{ is output-complete and }\lambda(\gamma_p)=0,\\
&\text{then }V\setminus V_p\text{ and }E\setminus E_p\text{ are RPA with respect to }p.\\
(P5)& \text{Two maps }F:X\to Y\text{ and }G:Y\to X\text{ define a one-to-one correspondence if }G(F(x))=x\text{ and }F(G(y))=y.
\end{array}
\]

\section*{Derivation}
Define the map from elementary RPA properties to labeled buffering structures:
\begin{align}
F\bigl(V\setminus V_p,E\setminus E_p,p\bigr)
&:=\gamma_p=(V_p,E_p\cup E_p^+) &&\text{by (P2)}.
\end{align}
By necessity,
\begin{align}
\lambda(F(V\setminus V_p,E\setminus E_p,p))
&=\lambda(\gamma_p)=0 &&\text{by (P3)}.
\end{align}
Thus \(F\) maps elementary RPA properties to labeled buffering structures. Define the reverse map:
\begin{align}
G(\gamma_p)
&:=(V\setminus V_p,E\setminus E_p,p). &&\text{outside variables specified by the label }p
\end{align}
By sufficiency,
\begin{align}
G(\gamma_p)\text{ is an elementary RPA property}
& &&\text{by (P4)}.
\end{align}
Check composition in both directions:
\begin{align}
G(F(V\setminus V_p,E\setminus E_p,p))
&=G(V_p,E_p\cup E_p^+) &&\text{definition of }F\\
&=(V\setminus V_p,E\setminus E_p,p) &&\text{definition of }G,\\
F(G(\gamma_p))
&=F(V\setminus V_p,E\setminus E_p,p) &&\text{definition of }G\\
&=(V_p,E_p\cup E_p^+) &&\text{definition of }F\\
&=\gamma_p. &&\text{definition of }\gamma_p
\end{align}
Therefore the correspondence is one-to-one by (P5).

\section*{Final Result}
\[
\boxed{\{\text{elementary RPA properties}\}\longleftrightarrow\{\text{labeled buffering structures}\}}
\]

\hfill$\blacksquare$

core_reasoning_9:
\section*{Claim}
Let \(p=\{p_1,\ldots,p_m\}\) be a finite set of parameters, and let each \(p_\mu\) have labeled buffering structure \(\gamma_\mu=(V_\mu,E_\mu\cup E_\mu^+)\). If
\[
V_p:=\bigcup_{\mu=1}^mV_\mu,
\qquad
E_p:=\bigcup_{\mu=1}^mE_\mu,
\qquad
\gamma_p:=(V_p,E_p\cup E_p^+),
\]
then \((V\setminus V_p,E\setminus E_p,p)\) is a generic RPA property.

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \gamma_\mu=(V_\mu,E_\mu\cup E_\mu^+)\text{ is a labeled buffering structure for }p_\mu.\\
(P2)& \lambda(\gamma_\mu)=0\text{ for each }\mu.\\
(P3)& V_p:=\bigcup_{\mu=1}^mV_\mu,\quad E_p:=\bigcup_{\mu=1}^mE_\mu.\\
(P4)& E_p^+\text{ is the minimal set of reactions making }\gamma_p:=(V_p,E_p\cup E_p^+)\text{ output-complete}.\\
(P5)& \text{Buffering structures are closed under finite union: if each }\lambda(\gamma_\mu)=0,\text{ then }\lambda(\bigcup_\mu\gamma_\mu)=0.\\
(P6)& \text{Law of localization: if }\gamma_p\text{ is output-complete and }\lambda(\gamma_p)=0,\text{ then outside species and outside non-added reactions are insensitive to all parameters in }p.\\
(P7)& \text{A generic RPA property }(V',E',p)\text{ means all species in }V'\text{ and reactions in }E'\text{ are insensitive to every parameter in }p.
\end{array}
\]

\section*{Derivation}
Form the union of the labeled buffering structures:
\begin{align}
\bigcup_{\mu=1}^m\gamma_\mu
&=\left(\bigcup_{\mu=1}^m V_\mu,\bigcup_{\mu=1}^m(E_\mu\cup E_\mu^+)\right) &&\text{definition of subnetwork union}\\
&\subseteq (V_p,E_p\cup E_p^+) &&\text{by (P3) and minimal output completion (P4)}\\
&=\gamma_p. &&\text{by (P4)}
\end{align}
The completed union is a buffering structure:
\begin{align}
\lambda(\gamma_p)
&=0 &&\text{by (P2), closure under union (P5), and output completion in (P4)}.
\end{align}
Apply localization to each parameter in \(p\):
\begin{align}
q\in p,
\quad v_i\in V\setminus V_p
&\Longrightarrow \partial_q\bar x_i=0 &&\text{by (P6)},\\
q\in p,
\quad e_A\in E\setminus E_p
&\Longrightarrow \partial_q\bar r_A=0 &&\text{by (P6)}.
\end{align}
Since this holds for every \(q\in p\),
\begin{align}
(V\setminus V_p,E\setminus E_p,p)\text{ is a generic RPA property}
& &&\text{by (P7)}.
\end{align}

\section*{Final Result}
\[
\boxed{(V\setminus V_p,E\setminus E_p,p)\text{ is a generic RPA property}}
\]

\hfill$\blacksquare$

core_reasoning_12:
\section*{Claim}
For an output-complete subnetwork \(\gamma\), split concentrations and reaction rates as \(x=(x_1,x_2)^T\) and \(r=(r_1,r_2)^T\), where subscript \(1\) is internal to \(\gamma\) and subscript \(2\) is external. If
\[
\begin{pmatrix}\dot x_1\\\dot x_2\end{pmatrix}
=
\begin{pmatrix}S_{11}&S_{12}\\S_{21}&S_{22}\end{pmatrix}
\begin{pmatrix}r_1\\r_2\end{pmatrix},
\]
then the external dynamics can be rewritten as
\[
\frac{d}{dt}(x_2-S_{21}S_{11}^+x_1)=
(S_{22}-S_{21}S_{11}^+S_{12})r_2+S_{21}c_{11},
\quad c_{11}\in\ker S_{11}.
\]

\section*{Premises}
\[
\begin{array}{ll}
(P1)& \dot x_1=S_{11}r_1+S_{12}r_2.\\
(P2)& \dot x_2=S_{21}r_1+S_{22}r_2.\\
(P3)& r_1=S_{11}^+\dot x_1-S_{11}^+S_{12}r_2+c_{11},\quad c_{11}\in\ker S_{11}.\\
(P4)& S^\sharp:=S_{22}-S_{21}S_{11}^+S_{12}.\\
(P5)& S_{21}S_{11}^+\text{ is constant in time.}
\end{array}
\]

\section*{Derivation}
Substitute the expression for \(r_1\) into the external equation:
\begin{align}
\dot x_2
&=S_{21}r_1+S_{22}r_2 &&\text{by (P2)}\\
&=S_{21}(S_{11}^+\dot x_1-S_{11}^+S_{12}r_2+c_{11})+S_{22}r_2 &&\text{by (P3)}\\
&=S_{21}S_{11}^+\dot x_1-S_{21}S_{11}^+S_{12}r_2+S_{21}c_{11}+S_{22}r_2 &&\text{distribute }S_{21}\\
&=S_{21}S_{11}^+\dot x_1+(S_{22}-S_{21}S_{11}^+S_{12})r_2+S_{21}c_{11} &&\text{collect }r_2\\
&=S_{21}S_{11}^+\dot x_1+S^\sharp r_2+S_{21}c_{11}. &&\text{by (P4)}
\end{align}
Move the first term to the left and use constancy:
\begin{align}
\dot x_2-S_{21}S_{11}^+\dot x_1
&=S^\sharp r_2+S_{21}c_{11} &&\text{rearrangement}\\
\frac{d}{dt}(x_2-S_{21}S_{11}^+x_1)
&=S^\sharp r_2+S_{21}c_{11} &&\text{by (P5)}\\
&=(S_{22}-S_{21}S_{11}^+S_{12})r_2+S_{21}c_{11}. &&\text{by (P4)}
\end{align}

\section*{Final Result}
\[
\boxed{\frac{d}{dt}(x_2-S_{21}S_{11}^+x_1)=
(S_{22}-S_{21}S_{11}^+S_{12})r_2+S_{21}c_{11}}
\]

\hfill$\blacksquare$

core_reasoning_14:
\section*{Claim}
If \(d^{(a)}=(d_1^{(a)},0)\) is an emergent conserved-quantity vector for a subnetwork split and
\[
(d^{(a)})^TS=(0,c_2^{(a)}),
\]
then it generates the integrator equation
\[
\frac{d}{dt}\bigl((d_1^{(a)})^Tx_1\bigr)=(c_2^{(a)})^Tr_2(x_2),
\]
and at steady state it imposes \((c_2^{(a)})^Tr_2(\bar x_2)=0\).

\section*{Premises}
\[
\begin{array}{ll}
(P1)& d^{(a)}=\begin{pmatrix}d_1^{(a)}\\0\end{pmatrix}.\\
(P2)& (d^{(a)})^TS=(0,c_2^{(a)}).\\
(P3)& \dot x=Sr.\\
(P4)& x=\begin{pmatrix}x_1\\x_2\end{pmatrix},\quad r=\begin{pmatrix}r_1\\r_2\end{pmatrix}.\\
(P5)& \text{At steady state, }\dfrac{d}{dt}\bigl((d_1^{(a)})^Tx_1\bigr)=0.
\end{array}
\]

\section*{Derivation}
Differentiate the linear combination of internal concentrations:
\begin{align}
\frac{d}{dt}\bigl((d_1^{(a)})^Tx_1\bigr)
&=(d_1^{(a)})^T\dot x_1 &&\text{linearity of }d/dt\\
&=(d^{(a)})^T\dot x &&\text{by (P1) and (P4)}\\
&=(d^{(a)})^TSr &&\text{by (P3)}\\
&=(0,c_2^{(a)})\begin{pmatrix}r_1\\r_2\end{pmatrix} &&\text{by (P2) and (P4)}\\
&=(c_2^{(a)})^Tr_2. &&\text{block multiplication}
\end{align}
At steady state,
\begin{align}
0&=(c_2^{(a)})^Tr_2(\bar x_2) &&\text{by previous line and (P5)}.
\end{align}

\section*{Final Result}
\[
\boxed{\frac{d}{dt}\bigl((d_1^{(a)})^Tx_1\bigr)=(c_2^{(a)})^Tr_2(x_2),\qquad (c_2^{(a)})^Tr_2(\bar x_2)=0}
\]

\hfill$\blacksquare$
